import {applyMedia,visibleMedia,mediaLink} from './media-state.js';
import {newId} from './cloud.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['小禾','阿远'];
export function createMediaUI({context,cloud,modal,close,toast,handlers,request,enter,bench,journal,record,save,returnOwnShelf}){
 const c=context;let items=[],binding={},busy=false,selected=null,loadError='',page=0;
 const key='echoo-media-v1';if(!cloud)try{items=JSON.parse(localStorage.getItem(key))||[]}catch{}
 const button=(a,label,id='')=>`<button class="pill" data-media="${a}" data-id="${esc(id)}">${label}</button>`;
 const link=(item)=>{const url=mediaLink(item.url,item.kind,true);return url?`<a class="pill" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${item.kind==='book'?'打开微信读书 ↗':'去 QQ 音乐收听 ↗'}</a>`:'<small>尚未添加阅读链接</small>'};
 const worldItems=kind=>visibleMedia(items,c().actor,cloud?cloud.paired:true).filter(x=>x.owner===c().world&&x.kind===kind);
 function updateModels(){c().visual?.media(items.filter(x=>x.owner===c().world));}
 async function load(){try{if(cloud){const r=await cloud.mediaView();items=r.items;binding=r.binding}else{items=JSON.parse(localStorage.getItem(key)||'[]')}loadError='';updateModels();return true}catch{loadError='暂时没有载入成功，请重新打开试试。';return false}}
 async function change(data){if(busy)return false;busy=true;try{
  if(cloud){const r=await cloud.media({world:c().world,...data});if(!r)return false;items=r.items;binding=r.binding;}
  else{const event=applyMedia(items,c().actor,true,{world:c().world,...data},Date.now(),newId);localStorage.setItem(key,JSON.stringify(items));if(event){c().state.events.unshift(event);save()}}
  updateModels();toast('已经收好。');return true;
 }catch(e){toast(e.message);return false}finally{busy=false}}
 async function shelf(){page=0;modal('bookshelf','THE BOOKS WE KEEP','小屋里的真实书架','<p role="status">正在整理书架…</p>');await load();if(c().panel==='bookshelf')renderShelf()}
 function renderShelf(){const books=worldItems('book'),own=c().world===c().actor;
  modal('bookshelf','THE BOOKS WE KEEP',own?'给喜欢的书，留一个位置':names[c().world]+'分享的书架',`<p class="subtle">${own?'把读过和想读的书收好，挑一本，带去长椅边。':'这里放着对方愿意与你分享的书。'}</p><div class="media-toolbar">${own?button('add-book','＋ 放一本书')+button('binding','微信读书同步'):''}${button('journal','共同手账')}</div>${loadError?`<p role="alert">${loadError}</p>`:''}<div class="real-bookshelf">${books.slice(page*12,page*12+12).map((b,i)=>`<button class="book-cover tone-${i%4}" data-media="book" data-id="${esc(b.id)}"><small>${esc(b.format||'一本喜欢的书')}</small><strong>${esc(b.title)}</strong><span>${esc(b.author||'待补充作者')}</span><i>${b.shared?'与对方分享':'仅自己可见'}${b.finished?' · 已读完':''}</i></button>`).join('')||'<p class="media-empty">书架还空着。<br>第一本，会是哪一本呢？</p>'}</div>${books.length>12?`<div class="media-toolbar">${page?button('prev','上一架'):''}<small>${page+1} / ${Math.ceil(books.length/12)}</small>${(page+1)*12<books.length?button('next','下一架'):''}</div>`:''}`)}
 function book(id){const b=items.find(x=>x.id===id);if(!b)return;selected=b;c().visual?.readingBook(b.title);
  modal('book','A PAGE TO REMEMBER',b.title,`<p class="subtle">${esc(b.author)} · ${b.shared?'与对方分享':'仅自己可见'}</p><div class="book-feature tone-0"><small>${esc(b.format||'READ AT YOUR OWN PACE')}</small><strong>${esc(b.title)}</strong><span>${esc(b.author)}</span></div><div class="media-toolbar">${link(b)}${button('bench','带到长椅读',b.id)}${b.owner===c().actor?button('share',b.shared?'改为自己可见':'分享给对方',b.id):''}${b.owner===c().actor?button('remove','从书架移走',b.id):''}</div><p class="subtle">正文在微信读书中阅读，这里留下一点自己的感想。</p>${noteForm(b)}${button('journal','翻开共同手账')}`)}
 function noteForm(b){return `<form class="media-form" data-media-form="note" data-id="${esc(b.id)}"><label>这一刻，想写下来<textarea name="message" maxlength="1000" required placeholder="读到这里，忽然想到了……"></textarea></label><label class="media-check"><input type="checkbox" name="shared"> 放进共同手账，让对方也能看到</label><button class="pill primary" type="submit">写进手账</button><p class="media-error" role="status"></p></form>`}
 function add(kind){modal('media-add','MAKE ROOM FOR SOMETHING YOU LOVE',kind==='book'?'放一本喜欢的书':'留一首歌给'+(c().world===c().actor?'自己':names[c().world]),`<form class="media-form" data-media-form="add" data-kind="${kind}"><label>${kind==='book'?'书名':'歌曲名'}<input name="title" maxlength="120" required></label><label>${kind==='book'?'作者':'歌手'}<input name="author" maxlength="120"></label><label>${kind==='book'?'微信读书链接（选填）':'QQ 音乐分享链接'}<input name="url" type="url" maxlength="2048" ${kind==='record'?'required':''} placeholder="https://..."></label>${kind==='book'?'<label class="media-check"><input name="shared" type="checkbox"> 分享给对方</label>':'<label>唱片套上的小留言<textarea name="message" maxlength="1000" placeholder="听见这首歌时，想起了你。"></textarea></label>'}<button class="pill primary" type="submit">${kind==='book'?'放进书架':'收进唱片架'}</button><p class="media-error" role="status"></p></form>`)}
 async function records(){modal('records','SONGS LEFT FOR YOU','为这一刻，留一首歌','<p role="status">正在整理唱片…</p>');await load();if(c().panel==='records')renderRecords()}
 function renderRecords(){modal('records','SONGS LEFT FOR YOU',names[c().world]+'的留歌唱片',`<p class="subtle">把一首歌和一句话，放在彼此的小屋里。</p><div class="media-toolbar">${button('add-record','＋ 留一首歌')}${button('journal','共同手账')}${button('melody','小屋原创旋律')}</div><div class="record-collection">${worldItems('record').slice().reverse().map(r=>`<article class="record-card"><div class="vinyl" aria-hidden="true"><span>♡</span></div><div><small>${names[r.addedBy]} 留下的歌</small><h3>${esc(r.title)}</h3><p>${esc(r.author)}</p><blockquote>${esc(r.message||'这首歌，想让你听见。')}</blockquote>${link(r)}${button('record','留言与回应',r.id)}${r.received?'<small>♡ 心意已收下</small>':''}</div></article>`).join('')||'<p class="media-empty">唱片机旁，等着一句「这首歌送给你」。</p>'}</div>`)}
 function recordDetail(id){const r=items.find(x=>x.id===id);if(!r)return;modal('record','A SONG, A LITTLE THOUGHT',r.title,`<div class="record-card"><div class="vinyl" aria-hidden="true"><span>♡</span></div><blockquote>${esc(r.message||'听到这首歌，想起了你。')}</blockquote></div><p class="subtle">${esc(r.author)} · ${names[r.addedBy]} 留在这里</p><div class="media-toolbar">${link(r)}${r.owner===c().actor&&!r.received?button('receive','收下这份心意',r.id):''}${button('remove','移走唱片',r.id)}</div>${noteForm(r)}`)}
 function bindingForm(){return `<form class="media-form" data-media-form="bind"><label for="weread-key">粘贴微信读书授权码<input id="weread-key" name="key" type="password" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="504" placeholder="以 wrk- 开头的 API Key" required></label><div class="binding-paste"><button class="pill" type="button" data-media="paste-key">粘贴授权码</button><small>也可以长按输入框粘贴</small></div><button type="submit" class="pill primary">绑定并同步我的书架</button><p class="media-error" role="status" aria-live="polite"></p></form>`}
 async function settings(result){modal('weread','YOUR READING CORNER','连接微信读书','<p role="status">正在查看连接状态…</p>');const loaded=await load();if(c().panel!=='weread')return;
  if(!loaded){modal('weread','YOUR READING CORNER','连接微信读书',`<p role="alert">连接状态暂时没有载入成功，请稍后重试。</p>${button('binding','重新载入')}`);return}
  const steps=`<div class="binding-step"><span class="binding-number">1</span><div><h3>去微信读书获取授权码</h3><p>在官方页面登录自己的账号，复制页面中的 <b>API Key</b>，然后回到阿球。</p><a class="pill primary binding-official" href="https://weread.qq.com/r/weread-skills" target="_blank" rel="noopener noreferrer">去微信读书授权 ↗</a><small>打开官方网页，完成后需要手动返回这里。</small></div></div><div class="binding-step"><span class="binding-number">2</span><div><h3>回来粘贴，书架就连接好了</h3>${bindingForm()}</div></div>`;
  modal('weread','YOUR READING CORNER',binding.connected?'你的书架，已经连起来了':'把喜欢的书，带回小屋',cloud?`<p class="subtle">只需绑定一次，以后点「同步书架」就好。两个人各自连接自己的微信读书。</p>${binding.connected?`<div class="binding-status" role="status"><b>✓ 微信读书已连接</b>${Number.isInteger(result?.imported)?'<p>本次同步了 '+result.imported+' 个书架条目。</p>':''}${binding.synced?'<small>最近同步：'+new Date(binding.synced).toLocaleString('zh-CN')+'</small>':''}</div><div class="media-toolbar">${button('own-shelf','去我的书架')+button('sync','同步书架')}</div><details class="binding-manage"><summary>更换授权或解除绑定</summary><p class="subtle">更换授权时，在官方页面重新获取 API Key，再粘贴到这里。</p>${steps}${button('disconnect','解除绑定')}</details>`:steps}<p class="binding-privacy">同步来的书默认仅自己可见。你可以逐本分享给对方；私人划线和笔记不会自动同步。</p><p class="subtle">授权码只交给你自己的阿球服务器保存，另一位住户看不到。解除绑定后，已经导入的书仍会保留。</p>${!binding.connected?button('own-shelf','先手动放一本书'):''}`:'<p>微信读书绑定需要登录云端版阿球。本地演示可以先手动放书。</p>');
 }
 async function bind(action,key){if(busy)return false;busy=true;try{const r=await cloud.weread({action,...(key?{key}:{})});if(!r)return false;items=r.items;binding=r.binding;updateModels();toast(action==='disconnect'?'已解除绑定，已导入的书仍保留。':`同步了 ${r.imported} 个书架条目。`);return r}finally{busy=false}}
 async function clicks(e){const b=e.target.closest('[data-media]');if(!b||b.disabled||busy)return;const id=b.dataset.id,item=items.find(x=>x.id===id);switch(b.dataset.media){
 case 'paste-key':{
 const input=document.querySelector('#weread-key'),status=document.querySelector('[data-media-form=bind] .media-error');
 try{if(!navigator.clipboard?.readText)throw Error();const value=(await navigator.clipboard.readText()).trim();if(!input.isConnected)return;if(!/^wrk-[A-Za-z0-9_-]{8,500}$/.test(value)){status.textContent='剪贴板中不是完整的授权码，请复制官方页面里以 wrk- 开头的 API Key。';return}input.value=value;status.textContent='已粘贴，请点击绑定并同步。'}catch{if(input?.isConnected){input.focus();status.textContent='浏览器没有允许读取剪贴板，请长按输入框，选择粘贴。'}}return;
 }
 case 'book':return book(id);case 'record':return recordDetail(id);case 'binding':return settings();case 'own-shelf':returnOwnShelf();return shelf();case 'journal':return journal('shared');case 'add-book':return add('book');case 'add-record':return add('record');case 'prev':page--;return renderShelf();case 'next':page++;return renderShelf();case 'melody':return handlers['legacy-music']();
 case 'bench':selected=item;close();return bench(item);case 'share':if(await change({type:'share',kind:item.kind,id,shared:!item.shared}))book(id);return;
 case 'remove':modal('media-remove','KEEP OR LET GO','把它移走？',`<p>移走《${esc(item.title)}》，已经写下的手账会保留。</p>${button('confirm-remove','确认移走',id)}`);return;
 case 'confirm-remove':if(await change({type:'remove',kind:item.kind,id}))item.kind==='book'?shelf():records();return;
 case 'receive':if(await change({type:'receive',kind:'record',id}))recordDetail(id);return;
 case 'sync':case 'disconnect':b.disabled=true;try{const result=await bind(b.dataset.media);if(result)await settings(result)}finally{b.disabled=false}return;
 }}
 document.querySelector('#panel-body').addEventListener('click',clicks);
 document.querySelector('#activity-dock').addEventListener('click',clicks);
 document.querySelector('#panel-body').addEventListener('submit',async e=>{const f=e.target;if(!f.matches('[data-media-form]'))return;e.preventDefault();if(busy)return;const data=Object.fromEntries(new FormData(f)),b=f.querySelector('button[type="submit"]');b.disabled=true;const status=f.querySelector('.media-error');status.textContent='正在保存…';let ok=false;
 try{if(f.dataset.mediaForm==='bind'){const key=data.key.trim();if(!/^wrk-[A-Za-z0-9_-]{8,500}$/.test(key)){status.textContent='请粘贴官方页面里以 wrk- 开头的完整 API Key。';return}status.textContent='正在验证授权并同步书架，请稍等…';ok=await bind('bind',key);if(ok){f.elements.key.value='';await settings(ok)}}
 else if(f.dataset.mediaForm==='add'){ok=await change({type:'add',kind:f.dataset.kind,...data,shared:!!data.shared});if(ok)f.dataset.kind==='book'?shelf():records()}
 else{const item=items.find(x=>x.id===f.dataset.id);ok=await change({type:'note',kind:item.kind,id:item.id,message:data.message,shared:!!data.shared});if(ok){f.reset();status.textContent='已写进'+(data.shared?'共同手账':'自己的手账')+'。'}}
 if(!ok&&status.isConnected)status.textContent='尚未保存，请查看提示并重试。';
 }catch(err){status.textContent=err.message||'连接失败，请稍后重试'}finally{b.disabled=false}});
 handlers.bookshelf=()=>request('bookshelf');handlers['weread-settings']=settings;handlers['legacy-music']=handlers.music;
 handlers.music=()=>request('music');
 function reading(){if(!selected)return null;return `<div class="dock-heading"><span>▤ ${esc(selected.title)}</span><button data-outdoor="leave" aria-label="起身离开">×</button></div><p class="subtle">${esc(selected.author)} · 在晚风里，留一点时间给自己。</p><div class="dock-actions">${link(selected)}${button('book','记一句读书感想',selected.id)}<button data-outdoor="page">轻轻翻一页 ↗</button></div>`}
 let lastWorld=c().world,lastActor=c().actor;setInterval(()=>{if(lastWorld!==c().world||lastActor!==c().actor){lastWorld=c().world;lastActor=c().actor;selected=null;c().visual?.readingBook('');load()}},1000);
 load();return {settings,reading,selected:()=>selected,show(a){if(a==='bookshelf'){shelf();return true}if(a==='music'){records();return true}return false}};
}
